sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float amount;
uniform float shape;
half4 main(float2 coord) {
    float2 h = size * 0.5;
    float2 p = (coord - h) / h;
    if (shape > 1.5) {
        float a = clamp(amount, -2.0, 2.0) * 0.5;
        float w = max(1.0 - a + a * p.y * p.y, 0.000001);
        float t = max(1.0 + a - a * p.x * p.x, 0.000001);
        float2 q = h + float2(p.x / w, p.y / t) * h;
        return image.eval(clamp(q, screen.xy + 0.5, screen.xy + screen.zw - 0.5));
    }
    float strength = amount;
    if (shape > 0.5 && strength < 0.0) p = p.yx;
    float a = (shape > 0.5 ? abs(strength) : strength) * 0.5;
    float squeeze = 1.0 - a * (1.0 - p.y * p.y);
    if (squeeze <= 0.0001) return half4(0.0);
    float2 q = float2(p.x / squeeze, p.y / (1.0 + 0.3 * abs(strength)));
    if (shape > 0.5 && strength < 0.0) q = q.yx;
    return image.eval(h + q * h);
}
